/**
 * Native constant-product pool helpers -- the TypeScript twin of the `boing pool` CLI
 * (`crates/boing-cli/src/pool.rs`). Signed transactions are byte-identical to the CLI for the same
 * signer, nonce and arguments (cross-checked in `tests/boingPool.test.ts` against
 * `tests/fixtures/pool-cli-vectors.json`, generated by the CLI's Rust tests).
 *
 * Wraps the v1..v8 pool templates (`docs/NATIVE-AMM-CALLDATA.md`). Custody: v1..v7 deposits and swap
 * inputs are ledger-only; v8 (default) pulls them with reference-token v2 `transfer_from`, so add /
 * swap first submit exact-amount `approve` txs unless `noApprove` -- see `docs/NATIVE-AMM-CLI.md`.
 */

import type { BoingClient } from './client.js';
import type { TransactionInput } from './bincode.js';
import { transactionIdFromSignedTransactionHex } from './bincode.js';
import { predictNonceDerivedContractAddress } from './create2.js';
import { NATIVE_CP_POOL_BYTECODE_HEX } from './defaultNativeCpPoolBytecodeHex.js';
import { hexToAccountId, hexToBytes, validateHex32 } from './hex.js';
import { calldataU128BeWord } from './calldata.js';
import { buildBoingTokenApproveTransaction } from './boingToken.js';
import {
  NATIVE_CP_SWAP_FEE_BPS,
  constantProductAmountOutFeeOnInputWithFeeBps,
  constantProductAmountOutWithFeeBps,
  encodeNativeAmmAddLiquidityCalldata,
  encodeNativeAmmRemoveLiquidityCalldata,
  encodeNativeAmmSetFeeAdminCalldata,
  encodeNativeAmmSetSwapFeeBpsCalldata,
  encodeNativeAmmSetTokensCalldata,
  encodeNativeAmmSwapCalldata,
  encodeNativeAmmSwapToCalldata,
} from './nativeAmm.js';
import {
  NATIVE_CONSTANT_PRODUCT_RESERVE_A_KEY_HEX,
  NATIVE_CONSTANT_PRODUCT_RESERVE_B_KEY_HEX,
  NATIVE_CONSTANT_PRODUCT_SWAP_FEE_BPS_KEY_HEX,
  NATIVE_CONSTANT_PRODUCT_TOKEN_A_KEY_HEX,
  NATIVE_CONSTANT_PRODUCT_TOKEN_B_KEY_HEX,
  NATIVE_CONSTANT_PRODUCT_TOTAL_LP_KEY_HEX,
  decodeBoingStorageWordU128,
  nativeAmmLpBalanceStorageKeyHex,
} from './nativeAmmPool.js';
import {
  fetchNextNonce,
  senderHexFromSecretKey,
  signTransactionInput,
  type Ed25519SecretKey32,
} from './transactionBuilder.js';

/** QA purpose category for pool deploys (CLI `POOL_PURPOSE`). */
export const BOING_POOL_PURPOSE = 'dapp';

export type BoingPoolVersion = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;
export const BOING_POOL_DEFAULT_VERSION: BoingPoolVersion = 8;

export const boingPoolHasTokenHooks = (v: BoingPoolVersion): boolean => v === 2 || v >= 4;
export const boingPoolHasStorageFee = (v: BoingPoolVersion): boolean => v >= 3;
export const boingPoolHasFeeAdmin = (v: BoingPoolVersion): boolean => v >= 6;
export const boingPoolHasRecipientSelectors = (v: BoingPoolVersion): boolean => v >= 5;
export const boingPoolFeeOnInput = (v: BoingPoolVersion): boolean => v >= 7;
/** v8 pulls deposits / swap input via reference-token v2 `transfer_from` (needs `approve`). */
export const boingPoolPullsTokens = (v: BoingPoolVersion): boolean => v === 8;

const withDeadline = (cd: Uint8Array, deadline: bigint): Uint8Array => {
  if (deadline < 0n || deadline >= 1n << 64n) throw new RangeError('deadline must fit in u64');
  const out = new Uint8Array(cd.length + 32);
  out.set(cd, 0);
  out.set(calldataU128BeWord(deadline), cd.length);
  return out;
};
/** v8 calldata: the v1..v7 layout plus a trailing deadline word (`0` = none). */
export const encodeBoingPoolV8SwapCalldata = (dir: bigint, amountIn: bigint, minOut: bigint, deadline = 0n) =>
  withDeadline(encodeNativeAmmSwapCalldata(dir, amountIn, minOut), deadline);
export const encodeBoingPoolV8SwapToCalldata = (dir: bigint, amountIn: bigint, minOut: bigint, toHex: string, deadline = 0n) =>
  withDeadline(encodeNativeAmmSwapToCalldata(dir, amountIn, minOut, toHex), deadline);
export const encodeBoingPoolV8AddLiquidityCalldata = (a: bigint, b: bigint, minLiquidity: bigint, deadline = 0n) =>
  withDeadline(encodeNativeAmmAddLiquidityCalldata(a, b, minLiquidity), deadline);
export const encodeBoingPoolV8RemoveLiquidityCalldata = (liquidity: bigint, minA: bigint, minB: bigint, deadline = 0n) =>
  withDeadline(encodeNativeAmmRemoveLiquidityCalldata(liquidity, minA, minB), deadline);

/** Template bytecode hex (what `boing pool bytecode --version vN` prints). */
export function boingPoolBytecodeHex(version: BoingPoolVersion = BOING_POOL_DEFAULT_VERSION): `0x${string}` {
  const h = NATIVE_CP_POOL_BYTECODE_HEX[version];
  if (!h) throw new Error(`unknown pool version ${version}`);
  return h;
}

/** Same as CLI `pool_access_list`: `[sender, pool, ...sorted unique non-zero extras]` on read and write. */
export function boingPoolAccessListHex(senderHex: string, poolHex: string, extrasHex: readonly string[] = []): string[] {
  const s = validateHex32(senderHex).toLowerCase();
  const p = validateHex32(poolHex).toLowerCase();
  const zero = `0x${'00'.repeat(32)}`;
  const ex = [...new Set(extrasHex.map((x) => validateHex32(x).toLowerCase()))]
    .filter((x) => x !== s && x !== p && x !== zero)
    .sort();
  return [s, p, ...ex];
}

/** Unsigned nonce-derived `ContractDeployWithPurpose` (purpose `dapp`). */
export function buildBoingPoolDeployTransaction(input: {
  nonce: bigint;
  senderHex: string;
  version?: BoingPoolVersion;
}): TransactionInput {
  const sender = hexToAccountId(validateHex32(input.senderHex));
  return {
    nonce: input.nonce,
    sender,
    payload: {
      kind: 'contractDeployWithPurpose',
      bytecode: hexToBytes(boingPoolBytecodeHex(input.version ?? BOING_POOL_DEFAULT_VERSION)),
      purposeCategory: BOING_POOL_PURPOSE,
      descriptionHash: null,
      create2Salt: null,
    },
    accessList: { read: [sender], write: [sender] },
  };
}

/** Unsigned pool `ContractCall` with the CLI access list. */
export function buildBoingPoolCallTransaction(input: {
  nonce: bigint;
  senderHex: string;
  poolHex: string;
  calldata: Uint8Array;
  extraAccountsHex?: readonly string[];
}): TransactionInput {
  const list = boingPoolAccessListHex(input.senderHex, input.poolHex, input.extraAccountsHex).map((h) =>
    hexToAccountId(h),
  );
  return {
    nonce: input.nonce,
    sender: hexToAccountId(validateHex32(input.senderHex)),
    payload: { kind: 'contractCall', contract: hexToAccountId(validateHex32(input.poolHex)), calldata: input.calldata },
    accessList: { read: list, write: [...list] },
  };
}

// --- math (mirrors pool bytecode and CLI helpers) ---

/** v1/v2: fixed 30 bps; v3..v7: stored word, `0` = unset -> 30. */
export function boingPoolEffectiveFeeBps(version: BoingPoolVersion, storedFeeBps: bigint): bigint {
  return !boingPoolHasStorageFee(version) || storedFeeBps === 0n ? BigInt(NATIVE_CP_SWAP_FEE_BPS) : storedFeeBps;
}

const U64_MAX = (1n << 64n) - 1n;

/** Quote `amount_out` exactly as the pool bytecode computes it for `version`. */
export function quoteBoingPoolAmountOut(
  version: BoingPoolVersion,
  reserveIn: bigint,
  reserveOut: bigint,
  amountIn: bigint,
  feeBps: bigint,
): bigint {
  for (const [v, w] of [[reserveIn, 'reserve'], [reserveOut, 'reserve'], [amountIn, 'amountIn']] as const) {
    if (v < 0n || v > U64_MAX) throw new RangeError(`${w} exceeds u64 (pool ledger limit)`);
  }
  return boingPoolFeeOnInput(version)
    ? constantProductAmountOutFeeOnInputWithFeeBps(reserveIn, reserveOut, amountIn, feeBps)
    : constantProductAmountOutWithFeeBps(reserveIn, reserveOut, amountIn, feeBps);
}

/** `floor(quote * (10000 - slippageBps) / 10000)`, at least 1 (CLI `min_out_with_slippage`). */
export function boingPoolMinOutWithSlippage(quote: bigint, slippageBps: bigint): bigint {
  if (slippageBps < 0n || slippageBps > 10_000n) throw new RangeError('slippageBps must be 0..10000');
  const m = (quote * (10_000n - slippageBps)) / 10_000n;
  return m < 1n ? 1n : m;
}

/** LP minted by `add_liquidity`: first mint min(a, b); then min(a*T/ra, b*T/rb). */
export function quoteBoingPoolLpMinted(ra: bigint, rb: bigint, totalLp: bigint, a: bigint, b: bigint): bigint {
  if (a === 0n || b === 0n) return 0n;
  if (totalLp === 0n) return a < b ? a : b;
  if (ra === 0n || rb === 0n) return 0n;
  const x = (a * totalLp) / ra;
  const y = (b * totalLp) / rb;
  return x < y ? x : y;
}

/** Amounts paid by `remove_liquidity(burn)`. */
export function quoteBoingPoolRemove(ra: bigint, rb: bigint, totalLp: bigint, burn: bigint): [bigint, bigint] {
  if (totalLp === 0n) return [0n, 0n];
  return [(burn * ra) / totalLp, (burn * rb) / totalLp];
}

// --- reads ---

export interface BoingPoolState {
  reserveA: bigint;
  reserveB: bigint;
  totalLp: bigint;
  storedFeeBps: bigint;
  tokenAHex: string;
  tokenBHex: string;
}

async function word(client: BoingClient, poolHex: string, keyHex: string): Promise<string> {
  const w = await client.getContractStorage(validateHex32(poolHex), keyHex);
  if (typeof w?.value !== 'string') throw new Error('unexpected boing_getContractStorage result');
  return w.value.toLowerCase();
}

/** `boing pool reserves`: reserves, total LP, stored fee word and token ids. */
export async function getBoingPoolState(client: BoingClient, poolHex: string): Promise<BoingPoolState> {
  const [ra, rb, t, f, ta, tb] = await Promise.all([
    word(client, poolHex, NATIVE_CONSTANT_PRODUCT_RESERVE_A_KEY_HEX),
    word(client, poolHex, NATIVE_CONSTANT_PRODUCT_RESERVE_B_KEY_HEX),
    word(client, poolHex, NATIVE_CONSTANT_PRODUCT_TOTAL_LP_KEY_HEX),
    word(client, poolHex, NATIVE_CONSTANT_PRODUCT_SWAP_FEE_BPS_KEY_HEX),
    word(client, poolHex, NATIVE_CONSTANT_PRODUCT_TOKEN_A_KEY_HEX),
    word(client, poolHex, NATIVE_CONSTANT_PRODUCT_TOKEN_B_KEY_HEX),
  ]);
  return {
    reserveA: decodeBoingStorageWordU128(ra),
    reserveB: decodeBoingStorageWordU128(rb),
    totalLp: decodeBoingStorageWordU128(t),
    storedFeeBps: decodeBoingStorageWordU128(f),
    tokenAHex: ta,
    tokenBHex: tb,
  };
}

export async function getBoingPoolLpBalance(client: BoingClient, poolHex: string, holderHex: string): Promise<bigint> {
  return decodeBoingStorageWordU128(await word(client, poolHex, nativeAmmLpBalanceStorageKeyHex(holderHex)));
}

export type BoingPoolDirection = 'a-to-b' | 'b-to-a';
const dirWord = (d: BoingPoolDirection): bigint => (d === 'a-to-b' ? 0n : 1n);

/** `boing pool quote`. */
export async function quoteBoingPoolSwap(
  client: BoingClient,
  input: { poolHex: string; direction: BoingPoolDirection; amountIn: bigint; version?: BoingPoolVersion; slippageBps?: bigint },
): Promise<{ amountOut: bigint; feeBps: bigint; minOut: bigint }> {
  const v = input.version ?? BOING_POOL_DEFAULT_VERSION;
  const s = await getBoingPoolState(client, input.poolHex);
  const [ri, ro] = input.direction === 'a-to-b' ? [s.reserveA, s.reserveB] : [s.reserveB, s.reserveA];
  const feeBps = boingPoolEffectiveFeeBps(v, s.storedFeeBps);
  const amountOut = quoteBoingPoolAmountOut(v, ri, ro, input.amountIn, feeBps);
  const m = boingPoolMinOutWithSlippage(amountOut, input.slippageBps ?? 50n);
  return { amountOut, feeBps, minOut: m < amountOut ? m : amountOut };
}

// --- signed flows ---

export interface BoingPoolSignedTx {
  txId: string;
  signedHex: string;
  submitted: boolean;
}

export interface BoingPoolSendOptions {
  nonce?: bigint;
  dryRun?: boolean;
}

/** v8-only options (CLI `--token-a/--token-b`, `--no-approve`, `--deadline-height`). */
export interface BoingPoolV8Options {
  /** Token ids (read from the pool when omitted; required offline). */
  tokenAHex?: string;
  tokenBHex?: string;
  /** Skip the automatic exact-amount `approve` tx(s). */
  noApprove?: boolean;
  /** Deadline block height (`0` = none). */
  deadlineHeight?: bigint;
}

async function send(
  client: BoingClient | null,
  tx: TransactionInput,
  secretKey32: Ed25519SecretKey32,
  dryRun: boolean,
): Promise<BoingPoolSignedTx> {
  const signedHex = await signTransactionInput(tx, secretKey32);
  const txId = transactionIdFromSignedTransactionHex(signedHex);
  if (!dryRun) {
    if (!client) throw new Error('a BoingClient is required to submit');
    await client.submitTransaction(signedHex);
  }
  return { txId, signedHex, submitted: !dryRun };
}

async function nonceFor(client: BoingClient | null, senderHex: string, nonce?: bigint): Promise<bigint> {
  if (nonce != null) return nonce;
  if (!client) throw new Error('pass a nonce or a BoingClient to fetch it');
  return fetchNextNonce(client, senderHex);
}

const offline = (client: BoingClient | null, o: BoingPoolSendOptions) => !client || (!!o.dryRun && o.nonce != null);

async function poolTokens(client: BoingClient | null, poolHex: string, o: BoingPoolV8Options, isOffline: boolean): Promise<[string, string]> {
  if (o.tokenAHex && o.tokenBHex) return [o.tokenAHex, o.tokenBHex];
  if ((o.tokenAHex == null) !== (o.tokenBHex == null)) throw new Error('pass both tokenAHex and tokenBHex (or neither)');
  if (isOffline || !client) throw new Error('offline v8 dry-run needs tokenAHex and tokenBHex');
  const s = await getBoingPoolState(client, poolHex);
  const zero = `0x${'00'.repeat(32)}`;
  if (s.tokenAHex === zero || s.tokenBHex === zero) throw new Error('pool has no tokens configured (is it really v8?)');
  return [s.tokenAHex, s.tokenBHex];
}

async function approveTx(
  client: BoingClient | null,
  secretKey32: Ed25519SecretKey32,
  senderHex: string,
  nonce: bigint,
  tokenHex: string,
  poolHex: string,
  amount: bigint,
  dry: boolean,
): Promise<BoingPoolSignedTx> {
  return send(client, buildBoingTokenApproveTransaction({ nonce, senderHex, tokenHex, toHex: poolHex, amount }), secretKey32, dry);
}

async function extrasWithTokens(
  client: BoingClient | null,
  poolHex: string,
  version: BoingPoolVersion,
  extras: readonly string[] | undefined,
  isOffline: boolean,
): Promise<string[]> {
  const out = [...(extras ?? [])];
  if (boingPoolHasTokenHooks(version) && !isOffline && client) {
    const s = await getBoingPoolState(client, poolHex);
    out.push(s.tokenAHex, s.tokenBHex);
  }
  return out;
}

export interface CreateBoingPoolInput extends BoingPoolSendOptions {
  version?: BoingPoolVersion;
  tokenAHex?: string;
  tokenBHex?: string;
  feeBps?: bigint;
  feeAdminHex?: string;
}

/** `boing pool create`: deploy, then optional set_tokens -> set_fee_admin -> set_swap_fee_bps (nonce+1..). */
export async function createBoingPool(
  client: BoingClient | null,
  secretKey32: Ed25519SecretKey32,
  input: CreateBoingPoolInput = {},
): Promise<{ deployerHex: string; poolHex: string; txs: BoingPoolSignedTx[] }> {
  const v = input.version ?? BOING_POOL_DEFAULT_VERSION;
  if ((input.tokenAHex == null) !== (input.tokenBHex == null)) throw new Error('pass both tokenAHex and tokenBHex (or neither)');
  if (input.tokenAHex && !boingPoolHasTokenHooks(v)) throw new Error(`pool v${v} has no token hooks`);
  if (boingPoolPullsTokens(v) && !input.tokenAHex) throw new Error('pool v8 needs tokenAHex and tokenBHex (reference fungible v2 tokens)');
  if (input.feeBps != null && (!boingPoolHasStorageFee(v) || input.feeBps < 1n || input.feeBps > 10_000n)) {
    throw new Error('feeBps needs v3..v8 and 1..10000');
  }
  if (input.feeAdminHex && !boingPoolHasFeeAdmin(v)) throw new Error('feeAdminHex needs v6..v8');
  const deployerHex = await senderHexFromSecretKey(secretKey32);
  let n = await nonceFor(client, deployerHex, input.nonce);
  const poolHex = predictNonceDerivedContractAddress(deployerHex, n);
  const dry = !!input.dryRun;
  const txs = [await send(client, buildBoingPoolDeployTransaction({ nonce: n, senderHex: deployerHex, version: v }), secretKey32, dry)];
  const call = (calldata: Uint8Array, extra: string[] = []) =>
    buildBoingPoolCallTransaction({ nonce: ++n, senderHex: deployerHex, poolHex, calldata, extraAccountsHex: extra });
  if (input.tokenAHex && input.tokenBHex) {
    txs.push(await send(client, call(encodeNativeAmmSetTokensCalldata(input.tokenAHex, input.tokenBHex), [input.tokenAHex, input.tokenBHex]), secretKey32, dry));
  }
  if (input.feeAdminHex) txs.push(await send(client, call(encodeNativeAmmSetFeeAdminCalldata(input.feeAdminHex)), secretKey32, dry));
  if (input.feeBps != null) txs.push(await send(client, call(encodeNativeAmmSetSwapFeeBpsCalldata(input.feeBps)), secretKey32, dry));
  return { deployerHex, poolHex, txs };
}

/**
 * `boing pool add-liquidity` (client-side min-liquidity preview when a client is available; v8 also
 * enforces it on-chain). v8: approve A at n, approve B at n+1, add at n+2 (unless `noApprove`);
 * `approvals` holds the approve txs.
 */
export async function addBoingPoolLiquidity(
  client: BoingClient | null,
  secretKey32: Ed25519SecretKey32,
  input: {
    poolHex: string;
    amountA: bigint;
    amountB: bigint;
    minLiquidity?: bigint;
    version?: BoingPoolVersion;
  } & BoingPoolSendOptions &
    BoingPoolV8Options,
): Promise<BoingPoolSignedTx & { expectedLp: bigint | null; approvals: BoingPoolSignedTx[] }> {
  const v = input.version ?? BOING_POOL_DEFAULT_VERSION;
  if (input.amountA <= 0n || input.amountB <= 0n) throw new Error('amounts must be > 0');
  const minLp = input.minLiquidity ?? 0n;
  let expectedLp: bigint | null = null;
  if (!offline(client, input) && client) {
    const s = await getBoingPoolState(client, input.poolHex);
    expectedLp = quoteBoingPoolLpMinted(s.reserveA, s.reserveB, s.totalLp, input.amountA, input.amountB);
    if (expectedLp === 0n) throw new Error('this deposit would mint 0 LP');
    if (expectedLp < minLp) throw new Error(`expected LP ${expectedLp} < minLiquidity ${minLp}`);
  }
  const senderHex = await senderHexFromSecretKey(secretKey32);
  let nonce = await nonceFor(client, senderHex, input.nonce);
  const dry = !!input.dryRun;
  const approvals: BoingPoolSignedTx[] = [];
  if (boingPoolPullsTokens(v)) {
    const [ta, tb] = await poolTokens(client, input.poolHex, input, offline(client, input));
    if (!input.noApprove) {
      approvals.push(await approveTx(client, secretKey32, senderHex, nonce, ta, input.poolHex, input.amountA, dry));
      approvals.push(await approveTx(client, secretKey32, senderHex, nonce + 1n, tb, input.poolHex, input.amountB, dry));
      nonce += 2n;
    }
    const tx = buildBoingPoolCallTransaction({
      nonce,
      senderHex,
      poolHex: input.poolHex,
      calldata: encodeBoingPoolV8AddLiquidityCalldata(input.amountA, input.amountB, minLp, input.deadlineHeight ?? 0n),
      extraAccountsHex: [ta, tb],
    });
    return { ...(await send(client, tx, secretKey32, dry)), expectedLp, approvals };
  }
  const tx = buildBoingPoolCallTransaction({
    nonce,
    senderHex,
    poolHex: input.poolHex,
    calldata: encodeNativeAmmAddLiquidityCalldata(input.amountA, input.amountB, minLp),
  });
  return { ...(await send(client, tx, secretKey32, dry)), expectedLp, approvals };
}

/** `boing pool remove-liquidity` (min_a/min_b derived from the pro-rata quote unless given). */
export async function removeBoingPoolLiquidity(
  client: BoingClient | null,
  secretKey32: Ed25519SecretKey32,
  input: {
    poolHex: string;
    liquidity: bigint;
    minA?: bigint;
    minB?: bigint;
    slippageBps?: bigint;
    version?: BoingPoolVersion;
    extraAccountsHex?: readonly string[];
  } & BoingPoolSendOptions &
    BoingPoolV8Options,
): Promise<BoingPoolSignedTx> {
  if (input.liquidity <= 0n) throw new Error('liquidity must be > 0');
  const v = input.version ?? BOING_POOL_DEFAULT_VERSION;
  const senderHex = await senderHexFromSecretKey(secretKey32);
  const isOff = offline(client, input);
  let { minA, minB } = input;
  if (minA == null || minB == null) {
    if (isOff || !client) throw new Error('offline dry-run needs explicit minA and minB');
    const s = await getBoingPoolState(client, input.poolHex);
    const mine = await getBoingPoolLpBalance(client, input.poolHex, senderHex);
    if (input.liquidity > mine) throw new Error(`liquidity ${input.liquidity} exceeds your LP balance ${mine}`);
    const [oa, ob] = quoteBoingPoolRemove(s.reserveA, s.reserveB, s.totalLp, input.liquidity);
    const sl = input.slippageBps ?? 50n;
    const cap = (m: bigint, o: bigint) => (m < o ? m : o);
    minA ??= cap(boingPoolMinOutWithSlippage(oa, sl), oa);
    minB ??= cap(boingPoolMinOutWithSlippage(ob, sl), ob);
  }
  let extras: string[];
  let calldata: Uint8Array;
  if (boingPoolPullsTokens(v)) {
    extras = [...(input.extraAccountsHex ?? []), ...(await poolTokens(client, input.poolHex, input, isOff))];
    calldata = encodeBoingPoolV8RemoveLiquidityCalldata(input.liquidity, minA, minB, input.deadlineHeight ?? 0n);
  } else {
    extras = await extrasWithTokens(client, input.poolHex, v, input.extraAccountsHex, isOff);
    calldata = encodeNativeAmmRemoveLiquidityCalldata(input.liquidity, minA, minB);
  }
  const nonce = await nonceFor(client, senderHex, input.nonce);
  const tx = buildBoingPoolCallTransaction({ nonce, senderHex, poolHex: input.poolHex, calldata, extraAccountsHex: extras });
  return send(client, tx, secretKey32, !!input.dryRun);
}

/** `boing pool swap`: on-chain `min_out` from a live quote + slippage unless `minOut` is given. */
export async function swapBoingPool(
  client: BoingClient | null,
  secretKey32: Ed25519SecretKey32,
  input: {
    poolHex: string;
    direction: BoingPoolDirection;
    amountIn: bigint;
    minOut?: bigint;
    slippageBps?: bigint;
    toHex?: string;
    version?: BoingPoolVersion;
    extraAccountsHex?: readonly string[];
  } & BoingPoolSendOptions &
    BoingPoolV8Options,
): Promise<BoingPoolSignedTx & { minOut: bigint; approvals: BoingPoolSignedTx[] }> {
  if (input.amountIn <= 0n) throw new Error('amountIn must be > 0');
  const v = input.version ?? BOING_POOL_DEFAULT_VERSION;
  const isOff = offline(client, input);
  let minOut = input.minOut;
  if (minOut == null) {
    if (isOff || !client) throw new Error('offline dry-run needs an explicit minOut');
    const q = await quoteBoingPoolSwap(client, { ...input, version: v, slippageBps: input.slippageBps ?? 50n });
    if (q.amountOut === 0n) throw new Error('quote is 0 (empty pool or amount too small)');
    minOut = boingPoolMinOutWithSlippage(q.amountOut, input.slippageBps ?? 50n);
  }
  if (minOut <= 0n) throw new Error('minOut must be > 0');
  if (input.toHex && !boingPoolHasRecipientSelectors(v)) throw new Error('toHex needs pool v5..v8 (swap_to)');
  const d = dirWord(input.direction);
  const dl = input.deadlineHeight ?? 0n;
  const pulls = boingPoolPullsTokens(v);
  const calldata = input.toHex
    ? pulls
      ? encodeBoingPoolV8SwapToCalldata(d, input.amountIn, minOut, input.toHex, dl)
      : encodeNativeAmmSwapToCalldata(d, input.amountIn, minOut, input.toHex)
    : pulls
      ? encodeBoingPoolV8SwapCalldata(d, input.amountIn, minOut, dl)
      : encodeNativeAmmSwapCalldata(d, input.amountIn, minOut);
  const senderHex = await senderHexFromSecretKey(secretKey32);
  let nonce = await nonceFor(client, senderHex, input.nonce);
  const dry = !!input.dryRun;
  const approvals: BoingPoolSignedTx[] = [];
  let extras: string[];
  if (pulls) {
    const [ta, tb] = await poolTokens(client, input.poolHex, input, isOff);
    if (!input.noApprove) {
      const tin = input.direction === 'a-to-b' ? ta : tb;
      approvals.push(await approveTx(client, secretKey32, senderHex, nonce, tin, input.poolHex, input.amountIn, dry));
      nonce += 1n;
    }
    extras = [...(input.extraAccountsHex ?? []), ta, tb];
  } else {
    extras = await extrasWithTokens(client, input.poolHex, v, input.extraAccountsHex, isOff);
  }
  const tx = buildBoingPoolCallTransaction({ nonce, senderHex, poolHex: input.poolHex, calldata, extraAccountsHex: extras });
  return { ...(await send(client, tx, secretKey32, dry)), minOut, approvals };
}